// Same shared secret every other inbound webhook in this project uses (REPLY_SECRET).
// The sheet is output-only, but the endpoint still reads the whole priced event table, so it
// is not left open.
const SECRET = 'playbook';
if ((($json.headers || {})['x-inbox-secret'] || '') !== SECRET) {
  throw new Error('401 Unauthorized: bad or missing x-inbox-secret');
}
return $input.all();

// Build the sheet rows. ONE ROW PER EVENT — the sheet is written with appendOrUpdate keyed
// on event_id, so re-running can never produce a duplicate row for a game.
//
// Freshness mirrors the Ticket Prices tab exactly (see ui/index.html, thresholdsFor/freshness):
// amber at the refresh cutoff for the tier, red at twice it. Both come from decider_rules, read
// above, so tuning the cadence tunes the sheet with it.
const r = $('Get Freshness Rules').first().json;
// Fail loudly rather than defaulting. Silently falling back to 3/48/12 would mislabel every
// row in the sheet if the rules read ever breaks, and nothing downstream would notice.
if (!r || r.price_near_days == null) {
  throw new Error('decider_rules unavailable — refusing to build the sheet on assumed thresholds');
}
const NEAR_DAYS   = Number(r.price_near_days ?? 3);
const AMBER_NEAR  = Number(r.price_stale_hours_near ?? 12);
const AMBER_FAR   = Number(r.price_stale_hours ?? 48);
const RED_MULT    = 2;

const SOURCE_NAMES = [
  [/stub\s*hub/i, 'StubHub'], [/seat\s*geek/i, 'SeatGeek'], [/vivid\s*seats/i, 'Vivid Seats'],
  [/ticket\s*master/i, 'Ticketmaster'], [/game\s*time/i, 'Gametime'], [/tick\s*pick/i, 'TickPick'],
  [/ticket\s*liquidator/i, 'Ticket Liquidator'], [/event\s*tickets\s*center/i, 'Event Tickets Center'],
  [/hello\s*tickets/i, 'Hellotickets'], [/cbs\s*sports/i, 'CBS Sports'], [/mlb\.com/i, 'MLB.com'],
];
// 'gemini' / 'openrouter' are the lookup route, not a marketplace — written when the model
// returned a price without naming where it read it. Calling that a source claims a provenance
// nobody has.
const UNNAMED = /^(gemini|openrouter|perplexity|sonar[-a-z.]*)$/i;
function sourceLabel(raw) {
  const t = String(raw || '').replace(/\s+/g, ' ').trim();
  if (!t) return '';
  if (t.toLowerCase() === 'manual') return 'Set by hand';
  if (UNNAMED.test(t)) return '';
  for (const [re, name] of SOURCE_NAMES) if (re.test(t)) return name;
  return t;
}

const SPORT = { mlb: 'Baseball', nfl: 'Football', nba: 'Basketball', nhl: 'Ice Hockey' };
const now = Date.now();
// TODAY IN ET, NOT THE SERVER'S CLOCK. n8n cloud runs in UTC, so setHours(0,0,0,0) gives UTC
// midnight — and between 00:00 and ~04:00 UTC (8pm to midnight ET) that is already tomorrow's
// date in ET terms. Every game sitting on the boundary would then be classified into the wrong
// freshness tier (12h/24h near vs 48h/96h far), which is the difference between "stale" and
// "fresh" on the same row depending on what hour the sync happened to run.
const ET = 'America/New_York';
const etYmd = d => d.toLocaleDateString('en-CA', { timeZone: ET });      // en-CA gives YYYY-MM-DD
const today = new Date(etYmd(new Date()) + 'T00:00:00');
const syncedAt = new Date().toLocaleString('en-US', { timeZone: ET,
  year: 'numeric', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) + ' ET';

function etString(iso) {
  if (!iso) return '';
  try {
    return new Date(iso).toLocaleString('en-US', { timeZone: 'America/New_York',
      year: 'numeric', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
  } catch { return ''; }
}

const out = [];
for (const item of $input.all()) {
  const e = item.json;
  if (!e || !e.id) continue;

  // Both sides are plain calendar dates at local midnight, so this is a whole-day difference
  // with no zone drift. event_date is deliberately NOT converted: it is the date the game is
  // played in its own city, not a timestamp, and shifting it would move west-coast games a day.
  const daysUntil = e.event_date
    ? Math.round((new Date(e.event_date + 'T00:00:00') - today) / 86400000)
    : null;

  const amber = (daysUntil != null && daysUntil <= NEAR_DAYS) ? AMBER_NEAR : AMBER_FAR;
  const red = amber * RED_MULT;

  let hours = '';
  let freshness;
  if (daysUntil != null && daysUntil < 0)      freshness = 'past';
  else if (e.best_price == null || !e.priced_at) freshness = 'never priced';
  else {
    hours = (now - new Date(e.priced_at).getTime()) / 3600000;
    freshness = hours >= red ? 'stale' : hours >= amber ? 'aging' : 'fresh';
    hours = Math.round(hours);
  }

  // Kick-off is stored UTC (MLB gameDate is UTC); shown in ET like every clock in the app.
  let kickoff = '';
  if (e.event_date && e.event_time) {
    const dt = new Date(e.event_date + 'T' + e.event_time + 'Z');
    if (!isNaN(dt)) kickoff = dt.toLocaleTimeString('en-US',
      { timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit' }) + ' ET';
  }

  out.push({ json: {
    event_id: e.id,
    external_id: e.external_id || '',
    event_date: e.event_date || '',
    kickoff_et: kickoff,
    matchup: e.opponent ? `${e.opponent} at ${e.team_full || e.team}` : (e.team_full || e.team || ''),
    sport: SPORT[String(e.league || '').toLowerCase()] || '',
    league: String(e.league || '').toUpperCase(),
    market: e.market_code || '',
    state_code: e.state_code || '',
    venue: e.venue || '',
    get_in_price_usd: e.best_price == null ? '' : Number(e.best_price),
    seats_basis: e.price_seats == null ? '' : e.price_seats,
    source: sourceLabel(e.price_source),
    source_raw: e.price_source || '',
    listing_url: e.price_url || '',
    last_refreshed_et: etString(e.priced_at),
    hours_since_refresh: hours,
    freshness,
    amber_after_hours: amber,
    red_after_hours: red,
    days_until: daysUntil == null ? '' : daysUntil,
    synced_at_est: syncedAt,
  } });
}

if (!out.length) throw new Error('No events built — refusing to write an empty sheet.');
return out;
